{"content":"import { Database } from "bun:sqlite";
import { schema } from "./schema";
import { join } from "path";
import { mkdirSync } from "fs";

const DB_PATH = join(process.cwd(), "data", "moment-diary.db");

// Ensure data directory exists
try {
  mkdirSync(join(process.cwd(), "data"), { recursive: true });
} catch (err) {
  // Ignore if exists
}

export const db = new Database(DB_PATH, { create: true });

// Enable foreign keys
db.run("PRAGMA foreign_keys = ON;");

// Initialize schema
export function initDB() {
  db.transaction(() => {
    // Bun's sqlite doesn't support multiple statements in one run() easily 
    // without some tricks, so we split by semicolon.
    const statements = schema
      .split(";")
      .map((s) => s.trim())
      .filter((s) => s.length > 0);

    for (const statement of statements) {
      db.run(statement);
    }
  })();
}

// Auto-init on load
initDB();
console.log("Database initialized at", DB_PATH);
